function(container, apiUrl, tables) {
  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'work_records_local';
  const SETTINGS_KEY = 'auto_save_settings';

  // 設定のデフォルト値
  let settings = {
    saveInterval: 30,
    maxLocalRecords: 100,
    autoSaveEnabled: true
  };

  // 設定を読み込み
  function loadSettings() {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      settings = { ...settings, ...JSON.parse(saved) };
    }
    container.querySelector('#save-interval').value = settings.saveInterval;
    container.querySelector('#max-local-records').value = settings.maxLocalRecords;
  }

  // 設定を保存
  function saveSettings() {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }

  // ローカルデータを取得
  function getLocalData() {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  // ローカルデータを保存
  function saveLocalData(data) {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
  }

  // ローカルデータテーブルを再描画
  function renderLocalData() {
    const localData = getLocalData();
    const tbody = container.querySelector('#local-data-tbody');

    tbody.innerHTML = localData.map(record => `
      <tr data-id="${record.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.id.substring(0, 8)}...</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.workerName || '未設定'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.workDate || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.projectName || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
                       background: ${record.synced ? '#22c55e' : '#f59e0b'}; color: #fff;">
            ${record.synced ? '同期済み' : '同期待ち'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.savedAt || ''}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary retry-sync-btn" data-id="${record.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); 
                         padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">
            再同期
          </button>
          <button class="action-btn secondary delete-local-btn" data-id="${record.id}"
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); 
                         padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">
            削除
          </button>
        </td>
      </tr>
    `).join('');

    // 同期待ちデータ件数を更新
    const pendingCount = localData.filter(r => !r.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;
  }

  // ネットワーク状態を更新
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    if (navigator.onLine) {
      statusEl.textContent = 'オンライン';
      statusEl.style.color = '#22c55e';
    } else {
      statusEl.textContent = 'オフライン';
      statusEl.style.color = '#ef4444';
    }
  }

  // エラー通知を表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // エラー通知を非表示
  function hideError() {
    container.querySelector('#error-notification').style.display = 'none';
  }

  // 最終保存時刻を更新
  function updateLastSaveTime() {
    const now = new Date();
    const timeStr = now.toLocaleTimeString('ja-JP', { hour12: false });
    container.querySelector('#last-save-time').textContent = timeStr;
  }

  // CSVエクスポート
  function exportToCSV() {
    const localData = getLocalData();
    if (localData.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['作業記録ID', '作業員名', '作業日', 'プロジェクト名', '同期状態', '保存時刻'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...localData.map(record => [
        record.id,
        record.workerName || '',
        record.workDate || '',
        record.projectName || '',
        record.synced ? '同期済み' : '同期待ち',
        record.savedAt || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `local_data_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 手動同期実行
  async function performManualSync() {
    const localData = getLocalData();
    const pendingData = localData.filter(r => !r.synced);

    if (pendingData.length === 0) {
      alert('同期待ちのデータはありません。');
      return;
    }

    let syncedCount = 0;
    for (const record of pendingData) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: record.workerId,
          作業日: record.workDate,
          作業開始時刻: record.startTime,
          作業終了時刻: record.endTime,
          プロジェクト名: record.projectName,
          作業場所: record.workLocation,
          作業種別: record.workType,
          作業内容: record.workContent,
          進捗状況: record.progress,
          承認状態: '未承認',
          作成者ID: record.workerId
        });

        if (saved) {
          record.synced = true;
          syncedCount++;
        }
      } catch (error) {
        console.error('同期エラー:', error);
      }
    }

    saveLocalData(localData);
    renderLocalData();

    if (syncedCount > 0) {
      alert(`${syncedCount}件のデータを同期しました。`);
      hideError();
    } else {
      showError('同期に失敗しました。ネットワーク接続を確認してください。');
    }
  }

  // データ復旧開始
  async function startDataRecovery() {
    const date = container.querySelector('#recovery-date').value;
    const method = container.querySelector('#recovery-method').value;

    if (!date) {
      alert('復旧対象日付を選択してください。');
      return;
    }

    try {
      // 指定日のデータを取得
      const allRecords = await window.aivicApi.list(1);
      if (!allRecords) {
        showError('データの取得に失敗しました。');
        return;
      }

      const targetRecords = allRecords.filter(r => 
        r.作業日 && r.作業日.startsWith(date)
      );

      if (targetRecords.length === 0) {
        alert('指定日のデータが見つかりませんでした。');
        return;
      }

      // ローカルストレージに復旧データを保存
      const recoveryData = targetRecords.map(record => ({
        id: record.作業記録ID,
        workerId: record.作業員ID,
        workerName: record.作業員名 || '不明',
        workDate: record.作業日,
        startTime: record.作業開始時刻,
        endTime: record.作業終了時刻,
        projectName: record.プロジェクト名,
        workLocation: record.作業場所,
        workType: record.作業種別,
        workContent: record.作業内容,
        progress: record.進捗状況,
        synced: true,
        savedAt: new Date().toLocaleString('ja-JP')
      }));

      const existingData = getLocalData();
      const mergedData = [...existingData, ...recoveryData];
      saveLocalData(mergedData);
      renderLocalData();

      alert(`${recoveryData.length}件のデータを復旧しました。`);
    } catch (error) {
      console.error('復旧エラー:', error);
      showError('データ復旧に失敗しました。');
    }
  }

  // バックアップ作成
  function createBackup() {
    const localData = getLocalData();
    const backupData = {
      timestamp: new Date().toISOString(),
      records: localData,
      settings: settings
    };

    const backupContent = JSON.stringify(backupData, null, 2);
    const blob = new Blob([backupContent], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `work_records_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  }

  // 初期化
  loadSettings();
  renderLocalData();
  updateNetworkStatus();
  updateLastSaveTime();

  // サンプルローカルデータを作成（初回のみ）
  if (getLocalData().length === 0) {
    const sampleData = [
      {
        id: 'local-001',
        workerId: 'user-001',
        workerName: '田中太郎',
        workDate: '2024-01-15',
        startTime: '09:00',
        endTime: '12:00',
        projectName: 'A棟設備点検',
        workLocation: 'A棟3階',
        workType: '点検',
        workContent: '空調設備の定期点検',
        progress: '完了',
        synced: false,
        savedAt: '2024-01-15 12:05:30'
      },
      {
        id: 'local-002',
        workerId: 'user-002',
        workerName: '佐藤花子',
        workDate: '2024-01-15',
        startTime: '13:00',
        endTime: '17:00',
        projectName: 'B棟配線工事',
        workLocation: 'B棟2階',
        workType: '設置',
        workContent: 'LAN配線の新設工事',
        progress: '作業中',
        synced: false,
        savedAt: '2024-01-15 14:30:15'
      },
      {
        id: 'local-003',
        workerId: 'user-003',
        workerName: '鈴木次郎',
        workDate: '2024-01-14',
        startTime: '10:00',
        endTime: '15:00',
        projectName: 'C棟修理作業',
        workLocation: 'C棟1階',
        workType: '修理',
        workContent: '照明器具の交換作業',
        progress: '完了',
        synced: true,
        savedAt: '2024-01-14 15:10:45'
      }
    ];
    saveLocalData(sampleData);
    renderLocalData();
  }

  // イベントリスナー設定
  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);

  container.querySelector('#btn-settings').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  });

  container.querySelector('#btn-update-settings').addEventListener('click', () => {
    settings.saveInterval = parseInt(container.querySelector('#save-interval').value);
    settings.maxLocalRecords = parseInt(container.querySelector('#max-local-records').value);
    saveSettings();
    alert('設定を更新しました。');
  });

  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカルデータをすべて削除しますか？この操作は取り消せません。')) {
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      renderLocalData();
      alert('ローカルデータを削除しました。');
    }
  });

  container.querySelector('#btn-export-local').addEventListener('click', exportToCSV);

  container.querySelector('#btn-dismiss-error').addEventListener('click', hideError);

  container.querySelector('#btn-start-recovery').addEventListener('click', startDataRecovery);

  container.querySelector('#btn-backup-create').addEventListener('click', createBackup);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const retrySyncBtn = e.target.closest('.retry-sync-btn');
    const deleteLocalBtn = e.target.closest('.delete-local-btn');

    if (retrySyncBtn) {
      const recordId = retrySyncBtn.dataset.id;
      const localData = getLocalData();
      const record = localData.find(r => r.id === recordId);

      if (record && !record.synced) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: record.workerId,
            作業日: record.workDate,
            作業開始時刻: record.startTime,
            作業終了時刻: record.endTime,
            プロジェクト名: record.projectName,
            作業場所: record.workLocation,
            作業種別: record.workType,
            作業内容: record.workContent,
            進捗状況: record.progress,
            承認状態: '未承認',
            作成者ID: record.workerId
          });

          if (saved) {
            record.synced = true;
            saveLocalData(localData);
            renderLocalData();
            alert('データを同期しました。');
            hideError();
          }
        } catch (error) {
          showError('同期に失敗しました。ネットワーク接続を確認してください。');
        }
      }
    }

    if (deleteLocalBtn) {
      if (confirm('このローカルデータを削除しますか？')) {
        const recordId = deleteLocalBtn.dataset.id;
        const localData = getLocalData();
        const filteredData = localData.filter(r => r.id !== recordId);
        saveLocalData(filteredData);
        renderLocalData();
      }
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 定期的な最終保存時刻更新（自動保存のシミュレーション）
  setInterval(() => {
    if (settings.autoSaveEnabled && navigator.onLine) {
      updateLastSaveTime();
    }
  }, settings.saveInterval * 1000);
}
